nextflow_process {

    name "Test Process CHEWBBACA_CREATESCHEMA"
    script "../main.nf"
    process "CHEWBBACA_CREATESCHEMA"

    tag "modules"
    tag "modules_nfcore"
    tag "chewbbaca"
    tag "chewbbaca/createschema"

    test("sarscov2 illumina contigs [fasta]") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fasta/contigs.fasta', checkIfExists: true)
                ]
                input[1] = [] // ptf
                input[2] = [] //cds
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    file(process.out.schema[0][1]).list().sort().findAll { file(it).name != ".genes_list" },
                    process.out.cds_coordinates,
                    process.out.invalid_cds,
                    process.out.findAll { key, val -> key.startsWith('versions') }
                ).match() }
            )
        }
    }

